import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen([script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    while True:
        try:
            if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                break
            cpu_usage += p.cpu_percent(interval=0.0)
            memory_usage += p.memory_info().rss
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
        if time.time() - start_time > timeout:
            proc.terminate()
            break
        time.sleep(0.1)
    if proc.poll() is None:
        proc.terminate()
        proc.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
